// Compose the address the analyzer expects. Works whether or not the
// optional Gemini normalize node above is enabled:
//  - disabled: $json is the raw sheet row → compose from columns
//  - enabled:  $json is the Gemini response → use normalized text,
//              falling back to the raw row referenced by node name.
const raw = $('Read addresses').item.json;
let normalized = '';
try { normalized = $json.candidates[0].content.parts[0].text.trim(); } catch (e) {}
const address = normalized || [raw.Address, raw.Boro_Area, raw.Zip].filter(Boolean).join(', ');
return { json: { address, boro_area: raw.Boro_Area || '', zip: raw.Zip || '' } };

// Gather every analyzed address into one payload for the report.
const results = $input.all().map(i => i.json);
return [{ json: { results, title: 'Cooling Tower Analysis' } }];
